INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('gyulkkeopjil', '귤껍질', '{"귤 껍질",감귤껍질,"말린 귤껍질","한라봉 껍질","오렌지 껍질","귤 상자",귤껍데기,"귤 껍데기",자몽껍질,"자몽 껍질",오렌지껍질,"곰팡이 핀 귤"}', '음식물', '음식물쓰레기입니다. 말려도 음식물쓰레기입니다.', '음식물', false, true, 2840, true, true, '2026-09-14 04:11:21.658012+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('jeondeung', '전등', '{LED등,엘이디등,led등,방등,거실등,평판등,천장등,등기구,"LED 조명",조명기구,"형광등 등기구",전등커버,"전등 커버",등커버,전등갓,컨버터,안정기,SMPS,무드등,수면등,취침등,"USB 무드등"}', '조건부', '전구만 빼면 수거함, 등기구째면 대형폐기물입니다.', '복합재질', false, true, 920, true, true, '2026-09-14 03:51:11.50863+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('chaek', '책', '{헌책,중고책,도서,단행본,양장본,만화책,동화책,전공서적,참고서,문제집,다이어리,수첩,플래너,공책,노트,"스프링 노트",다이어리}', '재활용', '종이류입니다. 코팅 표지와 스프링만 떼고, 양이 많으면 끈으로 묶습니다.', '종이류', false, false, 5550, true, true, '2026-09-14 04:11:21.658012+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('eunbakji', '은박지', '{호일,쿠킹호일,"알루미늄 호일","은박 접시",종이호일,담뱃갑,담배갑,"담배 포장지","은박 포장지","은박 라면용기",라면용기,"도시락김 포장지","즉석카레 봉지","레토르트 파우치","차량용 햇빛가리개",햇빛가리개}', '일반쓰레기', '알루미늄인데 캔이 아닙니다. 훈령이 금속캔에서 빼고 조례로 넘겼습니다.', '금속류', false, false, 1395, false, true, '2026-09-08 04:30:01.827996+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('hwilcheeo', '휠체어', '{전동휠체어,수동휠체어,보행기,보행보조기,전동스쿠터,목발,지팡이,"보행 지팡이"}', '조건부', '쓸 수 있으면 보조기기센터가 받습니다. 못 쓰면 대형폐기물입니다.', '생활용품', false, true, 55, true, true, '2026-09-07 07:44:01.345867+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('dongmulsache', '동물사체', '{"반려동물 사체","강아지 사체","고양이 사체","애완동물 사체","동물 시체"}', '조건부', '병원에서 죽었으면 병원이 처리합니다. 집에서 죽었으면 종량제봉투나 장묘업체, 매장은 과태료 100만원 이하입니다.', '생활폐기물', false, true, NULL, false, true, '2026-09-05 02:39:06.454529+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('chikinppyeo', '치킨뼈', '{닭뼈,돼지뼈,"돼지 뼈",감자탕뼈,등뼈,족발뼈,소뼈,사골뼈,닭발뼈,뼈다귀,치킨,"남은 치킨",닭고기,닭껍질,고기,"남은 고기",닭발,닭껍질,닭연골,"닭 털","생닭 손질","닭 껍질","닭 기름"}', '일반쓰레기', '음식물쓰레기가 아닙니다. 뼈는 기준에서 빠져 종량제봉투로 갑니다.', '음식물', false, false, 1890, true, true, '2026-09-14 04:42:17.714395+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('parasol', '파라솔', '{야외파라솔,캠핑파라솔,비치파라솔,그늘막파라솔,파라솔받침대}', '조건부', '살대는 고철, 천은 종량제봉투입니다. 통째로면 대형폐기물입니다.', '복합재질', false, true, 75, true, true, '2026-09-07 07:44:01.345867+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('godegi', '고데기', '{봉고데기,판고데기,"헤어 아이론",아이롱,무선고데기,볼륨매직기}', '전용수거함', '소형가전 수거함입니다. 충전식은 통째로, 완전히 식혀서 냅니다.', '폐전기전자제품', false, false, 1880, true, true, '2026-09-08 02:04:18.541008+00');
