INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('pyemokjae', '폐목재', '{"목재 쓰레기","나무 폐기물",각목,합판,"합판 조각",MDF,엠디에프,"나무 팔레트",파렛트,목재,장작,땔감,나무토막}', '조건부', '손바닥 크기 자투리는 종량제, 못 박힌 원목 조각이나 큰 판자는 대형폐기물 신고입니다.', '건축폐자재', false, true, NULL, true, true, '2026-09-14 03:51:11.50863+00');
