INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('noteubuk', '노트북', '{태블릿,아이패드,갤럭시탭,"고장난 태블릿"}', '조건부', '중소형이라 1대만으로는 무상수거가 안 됩니다. 5개 이상부터입니다.', '폐전기전자제품', false, false, 2080, true, true, '2026-09-04 05:51:40.471884+00');
