INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('waipeo', '와이퍼', '{와이퍼블레이드,자동차와이퍼,와이퍼고무,와이퍼암}', '조건부', '고무는 봉투, 금속 프레임은 고철입니다. 안 갈리면 통째로 봉투입니다.', '복합재질', false, false, 1240, true, true, '2026-09-07 08:07:16.063006+00');
