INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('aiseubakseu', '아이스박스', '{"아이스 박스","스티로폼 아이스박스","캠핑 아이스박스","하드 아이스박스","스티로폼 상자","스티로폼 박스"}', '조건부', '스티로폼 상자는 재활용, 캠핑용 하드 아이스박스는 종량제봉투나 대형폐기물입니다.', '복합재질', false, true, 610, true, true, '2026-09-08 02:32:12.571374+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('ribingbakseu', '리빙박스', '{수납박스,"리빙 박스",수납상자,정리함,"다용도 수납함"}', '조건부', '플라스틱이면 재활용, 천이면 종량제봉투입니다. 커지면 둘 다 대형폐기물입니다.', '플라스틱류', false, true, 560, false, true, '2026-09-08 03:37:33.69672+00');
