INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('seupikeo', '스피커', '{블루투스스피커,오디오,앰프,사운드바,우퍼,전축,오디오세트,"컴퓨터 스피커","오디오 스피커"}', '조건부', '손에 드는 크기는 소형가전 수거함, 전축 세트는 무상방문수거, 낱개 큰 것은 대형폐기물.', '폐전기전자제품', false, true, 280, true, true, '2026-09-08 00:27:54.708597+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('eumsingmulcheorigi', '음식물처리기', '{"음식물 처리기","음식물쓰레기 처리기","음식물 분쇄기",디스포저,"음식물 건조기",감량기}', '조건부', '소형가전이라 1대만으로는 무상수거를 못 부릅니다. 5개 이상이거나 대형가전과 함께입니다.', '폐전기전자제품', false, true, 670, false, true, '2026-09-08 03:37:33.69672+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('hangari', '항아리', '{장독,옹기,김칫독,단지}', '대형폐기물', '도자기라 재활용은 없습니다. 크면 마대가 아니라 신고입니다.', '도자기류', false, true, 555, true, true, '2026-09-07 06:22:36.943603+00');
