INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('bujikpo', '부직포', '{"부직포 포장재","부직포 옷커버","부직포 앞치마","정장 보관 가방","부직포 행주","부직포 커버",장바구니,"부직포 장바구니","부직포 가방",육수팩,"일회용 앞치마","부직포 마스크"}', '일반쓰레기', '합성섬유를 접착제로 굳힌 것이라 의류수거함도 재활용도 안 됩니다. 종량제봉투.', '섬유류', false, false, 660, true, true, '2026-09-08 04:30:01.827996+00');
