INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('banchantong', '반찬통', '{김치통,밀폐용기,락앤락,글라스락,"유리 반찬통","플라스틱 반찬통","스텐 반찬통","반찬 용기",요거트통,요구르트병,"떠먹는 요거트 용기"}', '조건부', '플라스틱은 플라스틱류, 스테인리스는 고철, 패킹은 종량제봉투. 유리 반찬통은 종량제봉투입니다.', '플라스틱류', false, false, 140, true, true, '2026-09-08 01:17:45.507279+00');
