INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('baiollin', '바이올린', '{비올라,첼로,통기타,우쿨렐레,현악기,악기,"기타 악기","바이올린 케이스",리코더,단소,오카리나,전자기타}', '조건부', '종량제봉투에 들어가면 종량제봉투, 기타와 첼로처럼 크면 대형폐기물입니다.', '복합재질', false, true, 155, false, true, '2026-09-08 01:17:45.507279+00');
