INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('jaseok', '자석', '{"냉장고 자석",냉장고자석,마그넷,"네오디뮴 자석","자석 교구",고무자석,강력자석,"자석 블록",화이트보드,자석칠판}', '일반쓰레기', '쇠에 붙지만 고철이 아닙니다. 종량제봉투에 넣습니다. 강력 자석은 종이로 감싸세요.', '복합재질', false, false, 190, true, true, '2026-09-08 01:17:45.507279+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('hanyak', '한약', '{"한약 찌꺼기",한약재,"한약 팩",첩약,약재,"한방차 찌꺼기",건강환,"한약 봉지","한약 파우치"}', '일반쓰레기', '폐의약품 수거함도 음식물도 아닙니다. 양쪽에서 다 빠져 종량제봉투입니다.', '음식물', false, false, 160, false, true, '2026-09-08 03:37:33.69672+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('aryeong', '아령', '{덤벨,바벨,케틀벨,원판,바벨원판,역기,철봉,"아쿠아 덤벨"}', '조건부', '고철입니다. 무거우면 대형폐기물로 kg당 값을 받는 곳이 있습니다.', '금속류', false, true, 980, true, true, '2026-09-07 08:07:16.063006+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('pomrolleo', '폼롤러', '{폼롤라,마사지볼,"필라테스 폼롤러",스파인코렉터,"마사지 롤러",요가링,"필라테스 링",마사지링,"운동 밴드",운동밴드,"스트레칭 밴드"}', '일반쓰레기', 'EVA, EPP 발포재라 재활용이 안 됩니다. 종량제봉투, 안 들어가면 대형폐기물.', '발포수지류', false, true, 1015, true, true, '2026-09-08 00:27:54.708597+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('pokjuk', '폭죽', '{불꽃놀이,스파클라,"파티 폭죽",꽃불,"안 쓴 폭죽","폭죽 처리",생일초}', '일반쓰레기', '물에 담가 적신 뒤 종량제봉투입니다. 유해폐기물이 아닙니다.', '복합재질', false, false, 145, false, true, '2026-09-08 01:17:45.507279+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('kaenbeoseu', '캔버스', '{유화,캔버스액자,캔버스천,아크릴화,그림,"수채화 물감","유화 물감","물감 튜브"}', '조건부', '종량제봉투입니다. 크면 대형폐기물입니다.', '복합재질', false, false, 245, true, true, '2026-09-07 08:07:16.063006+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('bakseu', '박스', '{택배박스,택배상자,종이박스,골판지,골판지상자,종이상자,라면박스,피자박스,치킨박스,상자,"커피믹스 상자","과자 상자",신발상자,"약 상자","화장품 상자"}', '재활용', '골판지는 다른 종이와 따로 묶어 냅니다. 테이프와 송장을 떼고, 보냉박스는 종량제봉투.', '종이류', true, false, 440, true, true, '2026-09-08 00:27:54.708597+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('bonaengbaek', '보냉백', '{보냉가방,보랭백,쿨러백,"보냉 가방",아이스가방,"은박 보냉백"}', '일반쓰레기', '은박과 부직포가 붙어 있어 분리가 안 됩니다. 크면 대형폐기물입니다.', '복합재질', false, false, 2130, false, true, '2026-09-08 02:32:12.571374+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('hyangsu', '향수', '{향수병,"디퓨저 오일",디퓨저,"디퓨저 스틱",룸스프레이,방향제,향수베이스,"향수 베이스"}', '조건부', '두꺼운 유리, 금속 펌프, 남은 알코올이 각각 다른 곳으로 갑니다.', '복합재질', false, false, 1385, true, true, '2026-09-04 05:51:40.471884+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('hyudaepongeochidae', '휴대폰 거치대', '{휴대폰거치대,"핸드폰 거치대",핸드폰거치대,"스마트폰 거치대",스마트폰거치대,폰거치대,"폰 거치대",거치대,"차량용 거치대","차량 거치대","송풍구 거치대","자석 거치대","무선충전 거치대","자바라 거치대","침대 거치대","노트북 거치대",노트북거치대,"노트북 스탠드","태블릿 거치대","아이패드 거치대","핸드폰 스탠드","휴대폰 스탠드"}', '조건부', '금속만이면 고철, 실리콘이나 자석이 붙어 있으면 종량제봉투입니다.', '복합재질', false, false, NULL, false, true, '2026-10-12 00:34:39.067977+00');
INSERT INTO public.items (slug, name, aliases, verdict, verdict_line, category, housing_split, region_varies, monthly_volume, competitor_has, published, updated_at) VALUES ('geimgi', '게임기', '{닌텐도,"닌텐도 스위치",닌텐도스위치,스위치2,"닌텐도 DS",3DS,게임보이,플스,플스4,플스5,플레이스테이션,PS4,PS5,PSP,엑스박스,Xbox,"콘솔 게임기",콘솔게임기,"휴대용 게임기","VR 기기","VR 게임기","VR 헤드셋","메타 퀘스트",오큘러스,조이콘,듀얼센스,"게임 컨트롤러",게임패드,"게임 패드",게임칩,"게임 카드",게임팩}', '전용수거함', '소형가전 수거함입니다. 넣기 전에 계정을 먼저 풀어 두세요.', '폐전기전자제품', false, false, NULL, false, true, '2026-10-12 00:34:39.067977+00');
